ns.Data:RegisterAttunement("ONYXIA", {  -- Onyxia's Lair
    note = "Finishing the chain gives you the {item:16309:Drakefire Amulet}, which opens Onyxia's Lair.",
    Alliance = {
        { id = 4182, name = "Dragonkin Menace", side = "Alliance", level = 54, minLevel = 48, xp = 5613, money = 16500, giver = "Helendis Riverhorn", giverNpc = 9562, kills = { { name = "Black Broodling", npc = 7047 }, { name = "Black Dragonspawn", npc = 7040 }, { name = "Black Drake", npc = 7044 }, { name = "Black Wyrmkin", npc = 7041 } }, objective = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete." },
        { id = 4183, name = "The True Masters", side = "Alliance", level = 54, minLevel = 48, xp = 4223, giver = "Helendis Riverhorn", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 9562, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 2, chain = { 4182 }, objective = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon." },
        { id = 4184, name = "The True Masters", side = "Alliance", level = 54, minLevel = 48, xp = 4223, giver = "Magistrate Solomon", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 344, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 3, chain = { 4182, 4183 }, objective = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.\n\nBolvar resides in Stormwind Keep." },
        { id = 4185, name = "The True Masters", side = "Alliance", level = 54, minLevel = 48, xp = 566, giver = "Highlord Bolvar Fordragon", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 1748, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 4, chain = { 4182, 4183, 4184 }, objective = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor." },
        { id = 4186, name = "The True Masters", side = "Alliance", level = 54, minLevel = 48, xp = 5613, giver = "Highlord Bolvar Fordragon", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 1748, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 5, chain = { 4182, 4183, 4184, 4185 }, objective = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire." },
        { id = 4223, name = "The True Masters", side = "Alliance", level = 54, minLevel = 48, xp = 566, giver = "Magistrate Solomon", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 344, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 6, chain = { 4182, 4183, 4184, 4185, 4186 }, objective = "Speak with Marshal Maxwell in the Burning Steppes." },
        { id = 4224, name = "The True Masters", side = "Alliance", level = 54, minLevel = 48, xp = 566, giver = "Marshal Maxwell", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 9560, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 7, chain = { 4182, 4183, 4184, 4185, 4186, 4223 }, objective = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.\n\nYou recall Marshal Maxwell telling you to search for him in a cave to the north." },
        { id = 4241, name = "Marshal Windsor", side = "Alliance", level = 54, minLevel = 48, xp = 11793, giver = "Marshal Maxwell", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 9560, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 8, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224 }, objective = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\n\nYou recall Ragged John talking about Windsor being dragged off to a prison." },
        { id = 4242, name = "Abandoned Hope", side = "Alliance", level = 54, minLevel = 48, xp = 10094, giver = "Marshal Windsor", chainStart = 4182, chainStartName = "Dragonkin Menace", giverInside = "BRD", chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 9, choice = { 12018, 12021, 12041 }, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241 }, objective = "Give Marshal Maxwell the bad news." },
        { id = 4264, name = "A Crumpled Up Note", side = "Alliance", level = 58, minLevel = 50, xp = 11484, startsFrom = "A Crumpled Up Note", startsFromId = 11446, chainStart = 4182, chainStartName = "Dragonkin Menace", chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 10, droppers = { { name = "Dark Keeper Vorfalk" }, { name = "Dark Keeper Zimrel" } }, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242 }, objective = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all." },
        { id = 4282, name = "A Shred of Hope", side = "Alliance", level = 58, minLevel = 50, xp = 11484, money = 9000, giver = "Marshal Windsor", chainStart = 4182, chainStartName = "Dragonkin Menace", giverInside = "BRD", chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 11, loot = { { item = 11464, name = "Marshal Windsor's Lost Information", from = { { name = "General Angerforge", inside = "BRD" }, { name = "Golem Lord Argelmach", inside = "BRD" } } } }, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264 }, objective = "Return Marshal Windsor's Lost Information.\n\nMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge." },
        { id = 4322, name = "Jail Break!", side = "Alliance", level = 58, minLevel = 50, xp = 14368, money = 17500, giver = "Marshal Windsor", chainStart = 4182, chainStartName = "Dragonkin Menace", giverInside = "BRD", chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 12, choice = { 12061, 12062 }, rewards = { 12065 }, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264, 4282 }, objective = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed." },
        { id = 6402, name = "Stormwind Rendezvous", side = "Alliance", level = 60, minLevel = 50, xp = 670, giver = "Marshal Maxwell", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 9560, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 13, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264, 4282, 4322 }, objective = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived." },
        { id = 6403, name = "The Great Masquerade", side = "Alliance", level = 60, minLevel = 50, xp = 9950, giver = "Reginald Windsor", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 12580, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 14, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264, 4282, 4322, 6402 }, objective = "Follow Reginald Windsor through Stormwind. Protect him from harm!" },
        { id = 6501, name = "The Dragon's Eye", side = "Alliance", level = 60, minLevel = 50, xp = 6600, giver = "Highlord Bolvar Fordragon", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 1748, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 15, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264, 4282, 4322, 6402, 6403 }, objective = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist." },
        { id = 6502, name = "Drakefire Amulet", side = "Alliance", level = 60, minLevel = 50, xp = 8300, giver = "Haleh", chainStart = 4182, chainStartName = "Dragonkin Menace", giverNpc = 10929, chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, chainStep = 16, loot = { { item = 16663, name = "Blood of the Black Dragon Champion", from = { { name = "General Drakkisath", inside = "UBRS" } } } }, rewards = { 16309 }, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264, 4282, 4322, 6402, 6403, 6501 }, objective = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire." },
    },
    Horde = {
        { id = 4903, name = "Warlord's Command", side = "Horde", level = 60, minLevel = 55, xp = 8300, money = 18000, startsFrom = "Warlord Goretooth's Command", startsFromId = 12563, kills = { { name = "Overlord Wyrmthalak", inside = "LBRS" }, { name = "Highlord Omokk", inside = "LBRS" }, { name = "War Master Voone", inside = "LBRS" } }, loot = { { item = 12562, name = "Important Blackrock Documents", from = { { name = "Spirestone Warlord", inside = "LBRS" }, { name = "Spirestone Battle Mage", inside = "LBRS" } } } }, choice = { 13958, 13959, 13961, 13962, 13963 }, objective = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished." },
        { id = 4941, name = "Eitrigg's Wisdom", side = "Horde", level = 60, minLevel = 55, xp = 6600, giver = "Warlord Goretooth", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 9077, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 2, chain = { 4903 }, objective = "Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.\n\nYou recall having seen Eitrigg in Thrall's chamber." },
        { id = 4974, name = "For The Horde!", side = "Horde", level = 60, minLevel = 55, xp = 9950, money = 27000, giver = "Thrall", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 4949, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 3, loot = { { item = 12630, name = "Head of Rend Blackhand", from = { { name = "Warchief Rend Blackhand", inside = "UBRS" } } } }, choice = { 13966, 13968, 13965 }, chain = { 4903, 4941 }, objective = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar." },
        { id = 6566, name = "What the Wind Carries", side = "Horde", level = 60, minLevel = 55, xp = 660, giver = "Thrall", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 4949, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 4, chain = { 4903, 4941, 4974 }, objective = "Listen to Thrall." },
        { id = 6567, name = "The Champion of the Horde", side = "Horde", level = 60, minLevel = 55, xp = 3300, giver = "Thrall", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 4949, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 5, chain = { 4903, 4941, 4974, 6566 }, objective = "Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas." },
        { id = 6568, name = "The Testament of Rexxar", side = "Horde", level = 60, minLevel = 55, xp = 4950, giver = "Rexxar", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 10182, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 6, chain = { 4903, 4941, 4974, 6566, 6567 }, objective = "Deliver Rexxar's Letter to Myranda the Hag in the Western Plaguelands." },
        { id = 6569, name = "Oculus Illusions", side = "Horde", level = 60, minLevel = 55, xp = 6600, giver = "Myranda the Hag", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 11872, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 7, loot = { { item = 16786, name = "Black Dragonspawn Eye", from = { { name = "Overlord Wyrmthalak", inside = "LBRS" }, { name = "Rage Talon Flamescale", inside = "UBRS" } } } }, chain = { 4903, 4941, 4974, 6566, 6567, 6568 }, objective = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete." },
        { id = 6570, name = "Emberstrife", side = "Horde", level = 60, minLevel = 55, xp = 4950, giver = "Myranda the Hag", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 11872, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 8, chain = { 4903, 4941, 4974, 6566, 6567, 6568, 6569 }, objective = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife." },
        { id = 6582, name = "The Test of Skulls, Scryer", level = 60, minLevel = 55, xp = 6600, giver = "Emberstrife", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 10321, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 9, loot = { { item = 16869, name = "The Skull of Scryer", from = { { name = "Scryer", npc = 10664 } } } }, chain = { 4903, 4941, 4974, 6566, 6567, 6568, 6569, 6570 }, objective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.\n\nYou know that Scryer can be found in Winterspring." },
        { id = 6583, name = "The Test of Skulls, Somnus", level = 60, minLevel = 55, xp = 6600, giver = "Emberstrife", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 10321, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 9, loot = { { item = 16870, name = "The Skull of Somnus", from = { { name = "Somnus", npc = 12900 } } } }, chain = { 4903, 4941, 4974, 6566, 6567, 6568, 6569, 6570 }, objective = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife." },
        { id = 6584, name = "The Test of Skulls, Chronalis", level = 60, minLevel = 55, xp = 6600, giver = "Emberstrife", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 10321, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 9, loot = { { item = 16871, name = "The Skull of Chronalis", from = { { name = "Chronalis", npc = 8197 } } } }, chain = { 4903, 4941, 4974, 6566, 6567, 6568, 6569, 6570 }, objective = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife." },
        { id = 6585, name = "The Test of Skulls, Axtroz", level = 60, minLevel = 55, xp = 6600, giver = "Emberstrife", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 10321, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 10, loot = { { item = 16872, name = "The Skull of Axtroz", from = { { name = "Axtroz", npc = 12899 } } } }, chain = { 4903, 4941, 4974, 6566, 6567, 6568, 6569, 6570, 6582 }, objective = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife." },
        { id = 6601, name = "Ascension...", side = "Horde", level = 60, minLevel = 55, xp = 4950, giver = "Emberstrife", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 10321, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 11, chain = { 4903, 4941, 4974, 6566, 6567, 6568, 6569, 6570, 6582, 6585 }, objective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next." },
        { id = 6602, name = "Blood of the Black Dragon Champion", side = "Horde", level = 60, minLevel = 55, xp = 9950, giver = "Rexxar", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 10182, chainStartItem = "Warlord Goretooth's Command", chainStartItemId = 12563, chainStep = 12, loot = { { item = 16663, name = "Blood of the Black Dragon Champion", from = { { name = "General Drakkisath", inside = "UBRS" } } } }, rewards = { 16309 }, chain = { 4903, 4941, 4974, 6566, 6567, 6568, 6569, 6570, 6582, 6585, 6601 }, objective = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar." },
